// Three main patterns for conditional rendering

function UserStatus({ user, isLoading, error }) {
    // Pattern 3: Early return for guard conditions
    if (isLoading) return <p>Loading...</p>;
    if (error)     return <p style={{ color: 'red' }}>Error: {error}</p>;
    if (!user)     return null;  // renders nothing

    return (
        <div>
            {/* Pattern 1: && — only render if true */}
            {user.isAdmin && <span>⭐ Admin</span>}

            <h2>{user.name}</h2>
            <p>{user.email}</p>

            {/* Pattern 2: ternary — one of two options */}
            {user.verified
                ? <span style={{ color: 'green' }}>✓ Verified</span>
                : <span style={{ color: 'orange' }}>⚠ Not verified</span>
            }
        </div>
    );
}

function App() {
    return (
        <div style={{ fontFamily: 'sans-serif', padding: '8px', display: 'flex', flexDirection: 'column', gap: '12px' }}>
            <UserStatus isLoading={true} />
            <UserStatus error="Network timeout" />
            <UserStatus user={null} />
            <UserStatus user={{ name: 'Alice', email: 'alice@example.com', isAdmin: true, verified: true }} />
            <UserStatus user={{ name: 'Bob', email: 'bob@example.com', isAdmin: false, verified: false }} />
        </div>
    );
}
